41	/// Create a [`NuTester`] for running Nushell snippets in tests.
42	///
43	/// Prefer this helper over the `nu!` macro for most tests.
44	/// It runs snippets in-process instead of shelling out to a subprocess, which makes tests faster
45	/// and lets you pass and read values directly without inferring from stdout or stderr.
46	/// The `nu!` macro executes the `nu` binary, and changes in a single crate might not trigger a
47	/// rebuild of that binary, so tests can run against stale behavior unless you run `cargo build`
48	/// first.
49	/// Using this helper avoids that by executing against the in-process engine components.
50	///
51	/// The tester starts from a default [`EngineState`] with the standard library loaded, and a fresh
52	/// [`Stack`].
53	/// Use the returned value to configure environment variables or the working directory before
54	/// running code.
55	///
56	/// # Environment behavior
57	///
58	/// - This tester does not inherit process environment variables.
59	/// - Any variables you want available to the engine must be added explicitly via
60	///   [`NuTester::env`] (or convenience helpers like [`NuTester::locale`]).
61	/// - Experimental options and other external environment settings are respected
62	///   when constructing the underlying engine state for the current test group.
63	///
64	/// # Examples
65	///
66	/// ```rust
67	/// use nu_test_support::prelude::*;
68	///
69	/// let code = "use std/util ellie; ellie | ansi strip";
70	/// let value: String = test().run(code)?;
71	/// assert_eq!(value, r#"
72	///      __  ,
73	///  .--()°'.'
74	/// '|, . ,'
75	///  !_-(_\
76	/// "#.trim_matches('\n'));
77	/// # Ok::<(), nu_test_support::tester::TestError>(())
78	/// ```
79	///
80	/// ```rust
81	/// use nu_test_support::prelude::*;
82	///
83	/// let mut tester = test()
84	///     .env("FOO", "bar")
85	///     .cwd("crates/nu-test-support");
86	///
87	/// let value: String = tester.run("$env.FOO")?;
88	/// assert_eq!(value, "bar");
89	/// # Ok::<(), nu_test_support::tester::TestError>(())
90	/// ```
91	pub fn test() -> NuTester {
92	    NuTester::default()
