//!
//! The [`Container`] trait unifies the various `contains`-style methods found on
//! standard library collections behind a single interface, so that generic code
//! can ask "does this thing contain that item?" without caring about the concrete
//! container type.

use std::collections::{BTreeMap, BTreeSet, HashMap, HashSet, LinkedList, VecDeque};
use std::hash::{BuildHasher, Hash};
use std::ops::{Range, RangeFrom, RangeInclusive, RangeTo, RangeToInclusive};

/// A type that can be queried for membership of some [`Item`](Container::Item).
///
/// This is implemented for the standard string and collection types, allowing
/// generic helpers to perform `contains` checks uniformly. Maps are considered to
/// contain their keys.
pub trait Container {
    /// The type of item that membership is checked against.
    ///
    /// This is allowed to be unsized (for example, [`str`]) so that string types
    /// can use `str` as their item type.
    type Item: ?Sized;

    /// Returns `true` if the container contains the given item.
    fn contains(&self, item: &Self::Item) -> bool;
}

impl Container for str {
    type Item = str;

    fn contains(&self, item: &str) -> bool {
        str::contains(self, item)
    }
}

impl Container for String {
    type Item = str;

    fn contains(&self, item: &str) -> bool {
        str::contains(self, item)
    }
}

impl<T: PartialEq, const N: usize> Container for [T; N] {
    type Item = T;

    fn contains(&self, item: &T) -> bool {
        <[T]>::contains(self, item)
    }
}

impl<T: PartialEq> Container for [T] {
    type Item = T;

    fn contains(&self, item: &T) -> bool {
        <[T]>::contains(self, item)
